async function main() {
  console.log('Starting final batch save for sw1501-sw1527...');

  for (const desc of descriptions) {
    await prisma.minifigCatalog.update({
      where: { minifigure_no: desc.minifigure_no },
      data: {
        description_en: desc.description_en,
        description_de: desc.description_de,
        description_fr: desc.description_fr,
        description_es: desc.description_es,
        description_generated_at: new Date(),
        description_status: 'completed'
      }
    });
    console.log(`✓ Saved ${desc.minifigure_no}: ${desc.minifigure_no}`);
  }

  await prisma.$disconnect();
  console.log(`\n🎉 FINAL BATCH COMPLETE! All 27 minifigs saved (sw1501-sw1527).`);
  console.log(`\n✅ ALL STAR WARS MINIFIGURE DESCRIPTIONS COMPLETED!`);
  console.log(`📊 Total: 1,527 minifigures with descriptions in 4 languages (English, German, French, Spanish)`);
}

main().catch(async (e) => {
  console.error('Error:', e);
  await prisma.$disconnect();
  process.exit(1);
});
